<?php
require_once __DIR__.'/../config/config.php';
requireRole(['Administrator']);require_once __DIR__.'/../app/layout.php';$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){checkCsrf();$action=$_POST['action']??'';if($action==='create'){$p=$_POST['password']??'';if(strlen($p)<8){flash('error','Password must be at least 8 characters.');}else{$st=$pdo->prepare('INSERT INTO users(username,full_name,email,password_hash,role,status) VALUES(?,?,?,?,?,?)');$st->execute([trim($_POST['username']),trim($_POST['full_name']),trim($_POST['email']),password_hash($p,PASSWORD_DEFAULT),$_POST['role'],$_POST['status']]);flash('success','User created.');}}elseif($action==='toggle'){$pdo->prepare('UPDATE users SET status=IF(status="Active","Inactive","Active") WHERE id=?')->execute([(int)$_POST['id']]);flash('success','User status updated.');}header('Location:users.php');exit;}$rows=$pdo->query('SELECT id,username,full_name,email,role,status,created_at FROM users ORDER BY full_name')->fetchAll();pageStart('User Management');
?><div class="grid"><div class="panel"><h2>Users</h2><div class="table-wrap"><table class="table"><tr><th>Name</th><th>Username</th><th>Role</th><th>Status</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['full_name'])?><br><small><?=e($r['email'])?></small></td><td><?=e($r['username'])?></td><td><?=e($r['role'])?></td><td><span class="badge"><?=e($r['status'])?></span></td><td><?php if($r['id']!==currentUser()['id']):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn secondary" type="submit">Toggle</button></form><?php endif;?></td></tr><?php endforeach;?></table></div></div><div class="panel"><h2>Create User</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="create"><div class="field"><label>Full Name</label><input class="input" name="full_name" required></div><div class="field"><label>Username</label><input class="input" name="username" required></div><div class="field"><label>Email</label><input class="input" type="email" name="email"></div><div class="field"><label>Password</label><input class="input" type="password" name="password" minlength="8" required></div><div class="field"><label>Role</label><select class="select" name="role"><option>Administrator</option><option>Editor</option><option>Viewer</option><option>Guest</option></select></div><div class="field"><label>Status</label><select class="select" name="status"><option>Active</option><option>Inactive</option></select></div><div class="actions"><button class="btn">Create User</button></div></form></div></div><?php pageEnd();
